import pyotp
import pytest

from app.auth import AuthError, get_session, login

ALICE_SECRET = "JBSWY3DPEHPK3PXP"


def alice_otp() -> str:
    return pyotp.TOTP(ALICE_SECRET).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", alice_otp())
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", alice_otp())
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", alice_otp())


def test_login_otp_incorrecto_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_acepta_cualquier_codigo_si_se_sustituye_verificacion(monkeypatch):
    monkeypatch.setattr("app.auth.verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "cualquier-cosa")
    assert s.username == "alice"


def test_endpoint_login(client):
    otp = alice_otp()  # alice y bob comparten secreto de prueba solo en este test auxiliar
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": pyotp.TOTP("KRSXG5CTMVRXEZLU").now()}
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": pyotp.TOTP("KRSXG5CTMVRXEZLU").now()}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401

